<%= turbo_frame_tag comment, :reactions do %>
  <div class="reactions" data-controller="reactions" data-reactions-refresh-url-value="<%= card_comment_reactions_path(comment.card, comment) %>">
    <div class="reactions__list" id="<%= dom_id(comment, :reaction_list) %>">
      <%= render "cards/comments/reactions/list", comment: comment %>
    </div>

    <button type="button" class="btn btn--circle reactions__trigger" title="Add a reaction" data-reactions-target="trigger" data-action="reactions#open">
      <%= image_tag "boost-color.svg", alt: "" %>
      <span class="for-screen-reader">Add a reaction</span>
    </button>

    <template data-reactions-target="template">
      <%= render "cards/comments/reactions/new", comment: comment, reaction: Reaction.new(comment: comment) %>
    </template>
  </div>
<% end %>
==========
<div class="reaction" id="<%= dom_id(comment, :new_reaction) %>" data-controller="morph-guard" data-reactions-target="form">
  <%= form_with model: reaction, url: card_comment_reactions_path(comment.card, comment), class: "reaction__form expanded" do |form| %>
    <label class="reaction__form-label">
      <span class="for-screen-reader">Reaction</span>
      <%= form.text_field :content, id: dom_id(comment, :reaction_content), class: "input reaction__input", placeholder: "React…", autocomplete: "off", required: true,
            aria: { invalid: reaction.errors.any? }, data: { action: "keydown.esc->reactions#close" } %>
    </label>

    <%= form.button class: "btn btn--circle reaction__submit-btn", title: "Add reaction" do %>
      <%= icon_tag "check" %>
      <span class="for-screen-reader">Add reaction</span>
    <% end %>

    <button type="button" class="btn btn--circle reaction__cancel-btn" title="Cancel" data-action="reactions#close">
      <%= icon_tag "close" %>
      <span class="for-screen-reader">Cancel</span>
    </button>
  <% end %>

  <% if reaction.errors.any? %>
    <span class="txt-small txt-negative" role="alert"><%= reaction.errors.full_messages.to_sentence %></span>
  <% end %>
</div>
"
